// ============================================================================
// UI Freeing
// ============================================================================

void ui_free(Widget* root) {
    if (!root) return;
    Widget_delete(root);
}

// ============================================================================
// Validation
// ============================================================================

bool ui_validate_json(const char* json) {
    if (!json || strlen(json) == 0) {
        return false;
    }

    // Check for basic required structure
    DynamicJsonDocument doc(UI_BUFFER_SIZE);
    DeserializationError error = deserializeJson(doc, json);

    if (error) {
        return false;
    }

    JsonObject root = doc.as<JsonObject>();

    // Must have type
    if (!root.containsKey(JSON_KEY_TYPE)) {
        return false;
    }

    // Check type is valid
    const char* type_str = root[JSON_KEY_TYPE];
    if (!type_str || ui_string_to_widget_type(type_str) == WIDGET_TYPE_COUNT) {
        return false;
    }

    return true;
}

// ============================================================================
// Integration with gui_loader_parse_json
// ============================================================================

// This function can be used by gui_loader_memory_safe.cpp and others
// It wraps the ArduinoJson parsing with memory-safe checks

extern "C" {

void* gui_loader_parse_json(const char* json) {
    // Ensure pools are initialized
    static bool pools_initialized = false;
    if (!pools_initialized) {
        pools_init();
        pools_initialized = true;
    }

    // Parse using ArduinoJson
    Widget* root = ui_parse_json(json);
    
    // Validate
    if (!root) {
        #ifdef GUIKIT_DEBUG
        Serial.println("Error: Failed to parse JSON");
        #endif
        return NULL;
    }

    return (void*)root;
}

}
